{# Feed pagination: cap the number of entries so the feed stays a manageable
   size once the archive grows large. `pages` is sorted newest-first, so the
   most recent posts are kept. Set config.extra.feed_limit to enable capping;
   leave it unset (or 0) to output every post. #}
{% set feed_limit = config.extra.feed_limit | default(value=0) %}
{% if feed_limit > 0 %}
    {% set feed_pages = pages | slice(end=feed_limit) %}
{% else %}
    {% set feed_pages = pages %}
{% endif %}

{% for page in feed_pages %}

    {{ page.title }}
    {{ page.permalink | safe }}

    {{ page.date | date(format="%+") }}
    {{ page.updated | default(value=page.date) | date(format="%+") }}
    {% if page.description %}
    {{ page.description }}
    {% endif %}
    {% if page.content %}
    {{ page.content }}
    {% endif %}
    {% if config.extra.github_username %}

        {{ config.extra.github_username }}
        {{ config.base_url }}

    {% endif %}

{% endfor %}
